-- ============================================================================
-- Wing Stop BD - Complete Database Schema
-- Full-Stack Ordering System with Multi-Role Support
-- ============================================================================

-- Users Table (Customers, Staff, Drivers, Admins)
CREATE TABLE users (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email VARCHAR(255) UNIQUE NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  phone_number VARCHAR(20),
  full_name VARCHAR(255) NOT NULL,
  role ENUM('customer', 'staff', 'driver', 'admin') NOT NULL DEFAULT 'customer',
  is_authorized BOOLEAN DEFAULT FALSE,
  address TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_email (email),
  INDEX idx_role (role),
  INDEX idx_phone (phone_number)
);

-- Menu Items Table
CREATE TABLE menu_items (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  description TEXT,\n  price DECIMAL(10, 2) NOT NULL,\n  category VARCHAR(100) NOT NULL,\n  image_url VARCHAR(500),\n  is_available BOOLEAN DEFAULT TRUE,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  INDEX idx_category (category),\n  INDEX idx_available (is_available)\n);\n\n-- Promos Table\nCREATE TABLE promos (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name VARCHAR(255) NOT NULL,\n  description TEXT,\n  discount_percentage DECIMAL(5, 2) NOT NULL,\n  discount_type ENUM('item', 'category', 'order') NOT NULL,\n  target_item_id UUID,\n  target_category VARCHAR(100),\n  is_active BOOLEAN DEFAULT TRUE,\n  start_date TIMESTAMP,\n  end_date TIMESTAMP,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  FOREIGN KEY (target_item_id) REFERENCES menu_items(id) ON DELETE SET NULL,\n  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE CASCADE,\n  INDEX idx_active (is_active),\n  INDEX idx_category (target_category)\n);\n\n-- Orders Table\nCREATE TABLE orders (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  order_number VARCHAR(50) UNIQUE NOT NULL,\n  customer_id UUID NOT NULL,\n  status ENUM('new', 'confirmed', 'preparing', 'out_for_delivery', 'delivered', 'cancelled') DEFAULT 'new',\n  total_amount DECIMAL(10, 2) NOT NULL,\n  discount_amount DECIMAL(10, 2) DEFAULT 0,\n  final_amount DECIMAL(10, 2) NOT NULL,\n  delivery_address TEXT NOT NULL,\n  customer_phone VARCHAR(20) NOT NULL,\n  customer_name VARCHAR(255) NOT NULL,\n  eta_minutes INT,\n  assigned_driver_id UUID,\n  assigned_staff_id UUID,\n  payment_status ENUM('pending', 'completed', 'refunded', 'failed') DEFAULT 'pending',\n  stripe_payment_id VARCHAR(255),\n  notes TEXT,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  FOREIGN KEY (customer_id) REFERENCES users(id) ON DELETE CASCADE,\n  FOREIGN KEY (assigned_driver_id) REFERENCES users(id) ON DELETE SET NULL,\n  FOREIGN KEY (assigned_staff_id) REFERENCES users(id) ON DELETE SET NULL,\n  INDEX idx_customer (customer_id),\n  INDEX idx_status (status),\n  INDEX idx_order_number (order_number),\n  INDEX idx_driver (assigned_driver_id),\n  INDEX idx_created (created_at)\n);\n\n-- Order Items Table (Line Items)\nCREATE TABLE order_items (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  order_id UUID NOT NULL,\n  menu_item_id UUID NOT NULL,\n  quantity INT NOT NULL DEFAULT 1,\n  unit_price DECIMAL(10, 2) NOT NULL,\n  discount_percentage DECIMAL(5, 2) DEFAULT 0,\n  subtotal DECIMAL(10, 2) NOT NULL,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,\n  FOREIGN KEY (menu_item_id) REFERENCES menu_items(id) ON DELETE RESTRICT,\n  INDEX idx_order (order_id)\n);\n\n-- Order Tracking Table\nCREATE TABLE order_tracking (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  order_id UUID NOT NULL,\n  status ENUM('new', 'confirmed', 'preparing', 'out_for_delivery', 'delivered', 'cancelled') NOT NULL,\n  eta_minutes INT,\n  updated_by UUID,\n  notes TEXT,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,\n  FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL,\n  INDEX idx_order (order_id),\n  INDEX idx_created (created_at)\n);\n\n-- Refunds Table\nCREATE TABLE refunds (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  order_id UUID NOT NULL,\n  amount DECIMAL(10, 2) NOT NULL,\n  reason VARCHAR(255),\n  status ENUM('pending', 'approved', 'processed', 'failed') DEFAULT 'pending',\n  stripe_refund_id VARCHAR(255),\n  requested_by UUID,\n  processed_by UUID,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  processed_at TIMESTAMP,\n  FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,\n  FOREIGN KEY (requested_by) REFERENCES users(id) ON DELETE SET NULL,\n  FOREIGN KEY (processed_by) REFERENCES users(id) ON DELETE SET NULL,\n  INDEX idx_order (order_id),\n  INDEX idx_status (status)\n);\n\n-- Authorized Emails Table (for role-based access control)\nCREATE TABLE authorized_emails (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  email VARCHAR(255) UNIQUE NOT NULL,\n  role ENUM('admin', 'staff', 'driver') NOT NULL,\n  is_active BOOLEAN DEFAULT TRUE,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  INDEX idx_email (email),\n  INDEX idx_role (role)\n);\n\n-- Notifications Table\nCREATE TABLE notifications (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL,\n  type ENUM('new_order', 'order_update', 'refund', 'cancellation', 'promo') NOT NULL,\n  title VARCHAR(255) NOT NULL,\n  message TEXT NOT NULL,\n  order_id UUID,\n  is_read BOOLEAN DEFAULT FALSE,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,\n  FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE SET NULL,\n  INDEX idx_user (user_id),\n  INDEX idx_read (is_read),\n  INDEX idx_created (created_at)\n);\n\n-- Audit Log Table\nCREATE TABLE audit_logs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID,\n  action VARCHAR(255) NOT NULL,\n  entity_type VARCHAR(100),\n  entity_id UUID,\n  old_values JSON,\n  new_values JSON,\n  ip_address VARCHAR(50),\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,\n  INDEX idx_user (user_id),\n  INDEX idx_entity (entity_type, entity_id),\n  INDEX idx_created (created_at)\n);\n\n-- ============================================================================\n-- INDEXES FOR PERFORMANCE\n-- ============================================================================\n\nCREATE INDEX idx_orders_customer_status ON orders(customer_id, status);\nCREATE INDEX idx_orders_driver_status ON orders(assigned_driver_id, status);\nCREATE INDEX idx_orders_staff_status ON orders(assigned_staff_id, status);\nCREATE INDEX idx_order_items_menu ON order_items(menu_item_id);\nCREATE INDEX idx_promos_dates ON promos(start_date, end_date);\nCREATE INDEX idx_notifications_user_read ON notifications(user_id, is_read);\n\n-- ============================================================================\n-- SAMPLE DATA\n-- ============================================================================\n\n-- Insert menu categories and items\nINSERT INTO menu_items (name, description, price, category, is_available) VALUES\n('BBQ Chicken Wings', 'Smoky BBQ sauce with perfect char', 350.00, 'wings', TRUE),\n('Honey Glazed Wings', 'Sweet honey glaze with savory notes', 340.00, 'wings', TRUE),\n('Dynamic Wings', 'Spicy kick with smooth finish', 320.00, 'wings', TRUE),\n('Naga Wings', 'Extremely spicy for heat lovers', 300.00, 'wings', TRUE),\n('Hot Korean Wings', 'Korean-inspired spicy glaze', 290.00, 'wings', TRUE),\n('Crispy Chicken Wings', 'Golden crispy with light seasoning', 250.00, 'wings', TRUE),\n('Classic Smash Smokey Beef', 'Smoky beef patty with premium toppings', 570.00, 'burgers', TRUE),\n('Classic Smash Beef', 'Juicy beef with fresh vegetables', 580.00, 'burgers', TRUE),\n('Classic Smash Chicken', 'Tender chicken breast burger', 470.00, 'burgers', TRUE),\n('Espresso (Single)', 'Rich, concentrated coffee shot', 220.00, 'coffee', TRUE),\n('Cappuccino', 'Smooth espresso with velvety foam', 280.00, 'coffee', TRUE),\n('Latte', 'Creamy coffee with steamed milk', 320.00, 'coffee', TRUE),\n('Vanilla Shake', 'Creamy vanilla milkshake', 300.00, 'drinks', TRUE),\n('Chocolate Shake', 'Rich chocolate milkshake', 300.00, 'drinks', TRUE),\n('Mint Lemonade', 'Refreshing mint and lemon blend', 180.00, 'drinks', TRUE);\n\n-- Insert authorized emails for role-based access\nINSERT INTO authorized_emails (email, role, is_active) VALUES\n('admin@wingstopbd.com', 'admin', TRUE),\n('staff@wingstopbd.com', 'staff', TRUE),\n('driver@wingstopbd.com', 'driver', TRUE);\n
